private static detectEndmark(lines: string[], blockStart: number): string {
    if (blockStart >= lines.length) { return '@'; }
    const firstRaw = lines[blockStart].replace(/[\r\n]+$/, '');
    return firstRaw.length > 0 ? firstRaw[firstRaw.length - 1] : '@';
}

private async _sendInitData(): Promise<void> {
    const context = this._context;
    const config = vscode.workspace.getConfiguration('figlet');
    const fontDir = config.get<string>('fontDirectory') || null;
    const lastFontUsed = context.globalState.get<string>('lastFontUsed') || 'small';
    const VALID_LAYOUT_KEYS = new Set<string>(['full', 'kerning', 'smush']);
    const rawLayout = config.get<string>('layoutMode') ?? 'smush';
    const defaultLayout = (VALID_LAYOUT_KEYS.has(rawLayout) ? rawLayout : 'smush') as LayoutKey;
    const language = this._editor.document.languageId;

    await FIGLetFontManager.setFontDirectory(fontDir);

    const fonts: Array<{ name: string; content: string }> = [];

    // Built-in default font
    try {
        const p = path.join(context.extensionPath, 'resources', 'fonts', 'small.flf');
        fonts.push({ name: 'small', content: await fs.readFile(p, 'utf-8') });
    } catch (e) {
        console.error('[FigletPanel] Failed to read default font:', e);
    }

    // User-configured fonts
    for (const info of FIGLetFontManager.availableFonts) {
        if (info.name !== 'small' && info.filePath) {
            try {
                fonts.push({ name: info.name, content: await fs.readFile(info.filePath, 'utf-8') });
            } catch { /* skip unreadable fonts */ }
        }
    }

    await this._panel.webview.postMessage({ type: 'init', fonts, defaultFont: lastFontUsed, defaultLayout, language });
}

private async _handleMessage(msg: FromWebview): Promise<void> {
    switch (msg.type) {
        case 'ready':
            await this._sendInitData();
            break;
        case 'ok':
            await this._insertBanner(msg);
            this.dispose();
            break;
        case 'cancel':
            this.dispose();
            break;
        case 'openExternal': {
            const ALLOWED_EXTERNAL_HOSTS = new Set([
                'marketplace.visualstudio.com',
                'code.visualstudio.com',
                'github.com',
            ]);
            const uri = vscode.Uri.parse(msg.url);
            if (uri.scheme === 'https' && ALLOWED_EXTERNAL_HOSTS.has(uri.authority)) {
                await vscode.env.openExternal(uri);
            }
            break;
        }
        case 'requestFont': {
            // Fonts are all sent eagerly in _init; handle late requests just in case
            const info = FIGLetFontManager.availableFonts.find(f => f.name === msg.name);
            if (info?.filePath) {
                try {
                    const content = await fs.readFile(info.filePath, 'utf-8');
                    await this._panel.webview.postMessage({ type: 'fontLoaded', name: msg.name, content });
                } catch { /* skip */ }
            }
            break;
        }
    }
}

private async _insertBanner(msg: OkMessage): Promise<void> {
    const editor = vscode.window.activeTextEditor || this._editor;
    const fontInfo = FIGLetFontManager.availableFonts.find(f => f.name === msg.font);
    const font: FIGFont = fontInfo?.font ?? await FIGFont.getDefault();

    const layoutMode =
        msg.layoutMode === 'full' ? LayoutMode.FullSize :
            msg.layoutMode === 'kerning' ? LayoutMode.Kerning :
                LayoutMode.Smushing;

    await this._context.globalState.update('lastFontUsed', msg.font);

    const figletText = new FIGLetRenderer(font, layoutMode).render(msg.text);
    await BannerUtils.insertBanner(editor, figletText, msg.language);
}

private async _sendInitData(): Promise<void> {
    const config = vscode.workspace.getConfiguration('figlet');
    const fontDirectory = config.get<string>('fontDirectory') || '';
    const VALID_LAYOUT_KEYS = new Set<string>(['full', 'kerning', 'smush']);
    const rawLayout = config.get<string>('layoutMode') ?? 'smush';
    const layoutMode = (VALID_LAYOUT_KEYS.has(rawLayout) ? rawLayout : 'smush') as LayoutKey;

    await FIGLetFontManager.setFontDirectory(fontDirectory || null);

    const fonts = await this._loadFonts();

    await this._panel.webview.postMessage({
        type: 'init',
        settings: { fontDirectory, layoutMode },
        fonts,
    });
}

private async _handleMessage(msg: FromWebview): Promise<void> {
    switch (msg.type) {
        case 'ready':
            await this._sendInitData();
            break;

        case 'browseFontDir': {
            const result = await vscode.window.showOpenDialog({
                canSelectFiles: false,
                canSelectFolders: true,
                canSelectMany: false,
                openLabel: 'Select Font Directory',
                title: 'Select FIGLet Font Directory',
            });
            if (result && result.length > 0) {
                const dir = result[0].fsPath;
                await FIGLetFontManager.setFontDirectory(dir);
                const fonts = await this._loadFonts();
                await this._panel.webview.postMessage({
                    type: 'fontDirectoryUpdated',
                    directory: dir,
                    fonts,
                });
            }
            break;
        }

        case 'saveSettings': {
            const { fontDirectory } = msg.settings;
            const VALID_LAYOUT_KEYS = new Set<string>(['full', 'kerning', 'smush']);
            const layoutMode = (VALID_LAYOUT_KEYS.has(msg.settings.layoutMode)
                ? msg.settings.layoutMode : 'smush') as LayoutKey;
            const config = vscode.workspace.getConfiguration('figlet');
            await config.update('fontDirectory', fontDirectory, vscode.ConfigurationTarget.Global);
            await config.update('layoutMode', layoutMode, vscode.ConfigurationTarget.Global);
            this.dispose();
            vscode.window.showInformationMessage('FIGLet settings saved.');
            break;
        }

        case 'close':
            this.dispose();
            break;
    }
}

constructor(
    primary: CommentStyle,
    singleLinePrefix: string | null = null,
    blockStart: string | null = null,
    blockEnd: string | null = null
) {
    this._primaryStyle = primary;

    switch (primary) {
        case CommentStyle.Custom:
            if (singleLinePrefix) {
                this._singleLinePrefix = singleLinePrefix;
            }
            if (blockStart && blockEnd) {
                this._blockCommentStart = blockStart;
                this._blockCommentEnd = blockEnd;
            }
            if (!singleLinePrefix && (!blockStart || !blockEnd)) {
                throw new Error("Custom comment style requires a single-line prefix, both block comment markers, or all three.");
            }
            break;

        case CommentStyle.CStyleBlock:
            this._blockCommentStart = blockStart ?? "/*";
            this._blockCommentEnd = blockEnd ?? "*/";
            this._singleLinePrefix = singleLinePrefix ?? "//";
            break;

        case CommentStyle.DoubleSlashes:
            this._singleLinePrefix = singleLinePrefix ?? "//";
            break;

        case CommentStyle.Hash:
            this._singleLinePrefix = singleLinePrefix ?? "#";
            break;

        case CommentStyle.Semicolon:
            this._singleLinePrefix = singleLinePrefix ?? ";";
            break;

        case CommentStyle.Quote:
            this._singleLinePrefix = singleLinePrefix ?? "'";
            break;

        case CommentStyle.MLComment:
            this._blockCommentStart = blockStart ?? "(*";
            this._blockCommentEnd = blockEnd ?? "*)";
            this._singleLinePrefix = singleLinePrefix ?? "//";
            break;

        case CommentStyle.HTML:
            this._blockCommentStart = blockStart ?? "<!--";
            this._blockCommentEnd = blockEnd ?? "-->";
            this._singleLinePrefix = null;
            break;

        case CommentStyle.SQLLine:
            this._blockCommentStart = blockStart ?? "/*";
            this._blockCommentEnd = blockEnd ?? "*/";
            this._singleLinePrefix = singleLinePrefix ?? "--";
            break;

        case CommentStyle.Pascal:
            this._blockCommentStart = blockStart ?? "{";
            this._blockCommentEnd = blockEnd ?? "}";
            this._singleLinePrefix = singleLinePrefix ?? "//";
            break;

        case CommentStyle.PowerShell:
            this._singleLinePrefix = singleLinePrefix ?? "#";
            this._blockCommentStart = blockStart ?? "<#";
            this._blockCommentEnd = blockEnd ?? "#>";
            break;

        case CommentStyle.Bash:
            this._singleLinePrefix = singleLinePrefix ?? "#";
            this._blockCommentStart = blockStart ?? ": '#";
            this._blockCommentEnd = blockEnd ?? "#'";
            break;

        case CommentStyle.BATCHFile:
            this._singleLinePrefix = singleLinePrefix ?? "::";
            break;

        default:
            throw new Error(`Invalid comment style: ${primary}`);
    }
}

