func run(cmd *cobra.Command, args []string) error {
	owner, repoName, prNumber, err := resolveTarget(args)
	if err != nil {
		return err
	}

	client, err := ghclient.NewClient(owner, repoName)
	if err != nil {
		return err
	}

	minimized, err := client.MinimizeCopilotComments(prNumber)
	if err != nil {
		return err
	}
	if minimized > 0 {
		fmt.Printf("Minimized %d outdated Copilot review comment(s)\n", minimized)
	}

	requested, err := client.IsCopilotReviewRequested(prNumber)
	if err != nil {
		return err
	}
	if requested {
		fmt.Println("Copilot review is already requested")
		return nil
	}

	pending, err := client.HasCopilotPendingReview(prNumber)
	if err != nil {
		return err
	}
	if pending {
		fmt.Println("Copilot review is in progress")
		return nil
	}

	fresh, err := client.IsCopilotReviewFresh(prNumber)
	if err != nil {
		return err
	}
	if fresh {
		fmt.Println("Copilot review is already up to date (newer than the last commit)")
		return nil
	}

	if err := client.RequestCopilotReview(prNumber); err != nil {
		return err
	}
	fmt.Printf("Copilot review requested on PR #%d\n", prNumber)

	return nil
}

func (c *Client) IsCopilotReviewFresh(prNumber int) (bool, error) {
	// Get the latest commit date on the PR
	var commits []struct {
		Commit struct {
			Committer struct {
				Date time.Time `json:"date"`
			} `json:"committer"`
		} `json:"commit"`
	}
	err := c.rest.Get(fmt.Sprintf("repos/%s/%s/pulls/%d/commits", c.owner, c.repo, prNumber), &commits)
	if err != nil {
		return false, fmt.Errorf("failed to get PR commits: %w", err)
	}
	if len(commits) == 0 {
		return false, nil
	}
	lastCommitDate := commits[len(commits)-1].Commit.Committer.Date

	// Get the latest Copilot review date
	var reviews []struct {
		User struct {
			Login string `json:"login"`
		} `json:"user"`
		SubmittedAt time.Time `json:"submitted_at"`
	}
	err = c.rest.Get(fmt.Sprintf("repos/%s/%s/pulls/%d/reviews", c.owner, c.repo, prNumber), &reviews)
	if err != nil {
		return false, fmt.Errorf("failed to get reviews: %w", err)
	}

	var latestCopilotReview time.Time
	for _, r := range reviews {
		if isCopilotUser(r.User.Login) && r.SubmittedAt.After(latestCopilotReview) {
			latestCopilotReview = r.SubmittedAt
		}
	}

	if latestCopilotReview.IsZero() {
		return false, nil
	}

	return latestCopilotReview.After(lastCommitDate), nil
}

