		if isCopilotUser(r.User.Login) && r.SubmittedAt.After(latestCopilotReview) {
			latestCopilotReview = r.SubmittedAt
		}
	}

	if latestCopilotReview.IsZero() {
		return false, nil
	}

	return latestCopilotReview.After(lastCommitDate), nil
}

func run(cmd *cobra.Command, args []string) error {
	owner, repoName, prNumber, err := resolveTarget(args)
	if err != nil {
		return err
	}

	client, err := ghclient.NewClient(owner, repoName)
	if err != nil {
		return err
	}

	minimized, err := client.MinimizeCopilotComments(prNumber)
	if err != nil {
		return err
	}
	if minimized > 0 {
		fmt.Printf("Minimized %d outdated Copilot review comment(s)\n", minimized)
	}

	requested, err := client.IsCopilotReviewRequested(prNumber)
	if err != nil {
		return err
	}
	if requested {
		fmt.Println("Copilot review is already requested")
		return nil
	}

	pending, err := client.HasCopilotPendingReview(prNumber)
	if err != nil {
		return err
	}
	if pending {
		fmt.Println("Copilot review is in progress")
		return nil
	}

	if err := client.RequestCopilotReview(prNumber); err != nil {
		return err
	}
	fmt.Printf("Copilot review requested on PR #%d\n", prNumber)

	return nil
}

func (c *Client) RequestCopilotReview(prNumber int) error {
	_, _, err := gh.Exec("pr", "edit", fmt.Sprintf("%d", prNumber),
		"--add-reviewer", "@copilot",
		"--repo", fmt.Sprintf("%s/%s", c.owner, c.repo))
	if err != nil {
		return fmt.Errorf("failed to request Copilot review: %w", err)
	}
	return nil
}

