    let snapshot = CredentialSnapshot::new(
        "api_key",
        CredentialMetadata::new(),
        SecretToken::new(SecretString::new("test-secret")),
    );

    let ctx = TestContextBuilder::new()
        .with_credential_snapshot("my_cred", snapshot)
