fn sanitize_id(input: &str) -> String {
    input.replace("..", "_").replace(['/', '\\', '\0'], "_")
}

fn date_parts(timestamp_millis: i64) -> (i32, u32, u32) {
    use chrono::{DateTime, Datelike, Utc};
    let dt = DateTime::<Utc>::from_timestamp_millis(timestamp_millis)
        .unwrap_or_else(|| DateTime::<Utc>::from_timestamp(0, 0).unwrap());
    (dt.year(), dt.month(), dt.day())
}

fn screenshot_path(
    base_dir: &std::path::Path,
    timestamp: i64,
    display_id: &str,
) -> std::path::PathBuf {
    let safe_id = sanitize_id(display_id);
    let (year, month, day) = date_parts(timestamp);
    base_dir
        .join("screenshots")
        .join(format!("{}/{:02}/{:02}", year, month, day))
        .join(format!("{}_{}.heif", timestamp, safe_id))
}

fn audio_path(base_dir: &std::path::Path, timestamp: i64, source: &str) -> std::path::PathBuf {
    let safe_source = sanitize_id(source);
    let (year, month, day) = date_parts(timestamp);
    base_dir
        .join("audio")
        .join(format!("{}/{:02}/{:02}", year, month, day))
        .join(format!("{}_{}.opus", timestamp, safe_source))
}

pub struct Storage {
    pub(crate) pool: Pool<SqliteConnectionManager>,
    pub(crate) base_dir: PathBuf,
    media_mgr: MediaManager,
}

pub async fn open(config: StorageConfig) -> Result<Self> {
    let base_dir = config.base_dir.clone();
    let pool_size = u32::try_from(config.pool_size)
        .map_err(|_| StorageError::Other("pool_size too large".into()))?;

    let db_path = base_dir.join("chronicle.db");
    let manager = SqliteConnectionManager::file(&db_path);

    let pool = tokio::task::spawn_blocking(move || {
        std::fs::create_dir_all(&base_dir)?;

        // Harden base directory permissions.
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&base_dir, std::fs::Permissions::from_mode(0o700))?;

        let pool = Pool::builder()
            .max_size(pool_size)
            .connection_customizer(Box::new(ConnectionCustomizer))
            .build(manager)?;

        let conn = pool.get()?;
        schema::migrate(&conn)?;

        // Harden DB file permissions.
        let db_file = base_dir.join("chronicle.db");
        if db_file.exists() {
            std::fs::set_permissions(&db_file, std::fs::Permissions::from_mode(0o600))?;
        }

        Ok::<_, StorageError>(pool)
    })
    .await??;

    let base_dir = config.base_dir;
    let media_mgr = MediaManager::new(base_dir.clone())?;
    Ok(Self {
        pool,
        base_dir,
        media_mgr,
    })
}

