    // dispatch event 'refresh ' to chatlist
    $this->dispatch('refresh')->to(Chats::class);

    // scroll to bottom
    $this->dispatch('scroll-bottom');

    // dispatch event
    $this->dispatchMessageCreatedEvent($message);
}

def resolution
  @property = :resolution
  fetch unless defined?(@resolution)
  @resolution
end

def initialize(stream, parse_resolution: false)
  @stream = stream
  @width, @height, @orientation = nil
  @x_resolution, @y_resolution, @resolution_unit = nil
  @parse_resolution = parse_resolution
  parse_exif
end

def parse_exif
  @start_byte = @stream.pos

  get_exif_byte_order

  @stream.read(2) # 42

  offset = @stream.read(4).unpack(@long)[0]
  if @stream.respond_to?(:skip)
    @stream.skip(offset - 8)
  else
    @stream.read(offset - 8)
  end

  parse_exif_ifd

  @orientation ||= 1
end

